// EncodeLine is a Line as a Buzz map.
func EncodeLine(v lib.Line) map[string]any {
	return map[string]any{
		"text":  v.Text,
		"style": string(v.Style),
		"spans": convert.EncodeList(v.Spans, func(x lib.Span) any { return EncodeSpan(x) }),
	}
}

// DecodeLine reads a Line from a Buzz map. A missing key reads as the zero value.
func DecodeLine(v any) (lib.Line, error) {
	var out lib.Line
	m, err := convert.Map(v)
	if err != nil {
		return out, err
	}
	if out.Text, err = convert.String(m["text"]); err != nil {
		return out, fmt.Errorf("text: %w", err)
	}
	if out.Style, err = convert.StringAs[lib.SGR](m["style"]); err != nil {
		return out, fmt.Errorf("style: %w", err)
	}
	if out.Spans, err = convert.DecodeSlice(m["spans"], func(x any) (lib.Span, error) { return DecodeSpan(x) }); err != nil {
		return out, fmt.Errorf("spans: %w", err)
	}
	return out, nil
}

