// EncodeSpan is a Span as a Buzz map.
func EncodeSpan(v lib.Span) map[string]any {
	return map[string]any{
		"text":  v.Text,
		"style": string(v.Style),
		"key":   v.Key,
	}
}

// DecodeSpan reads a Span from a Buzz map. A missing key reads as the zero value.
func DecodeSpan(v any) (lib.Span, error) {
	var out lib.Span
	m, err := convert.Map(v)
	if err != nil {
		return out, err
	}
	if out.Text, err = convert.String(m["text"]); err != nil {
		return out, fmt.Errorf("text: %w", err)
	}
	if out.Style, err = convert.StringAs[lib.SGR](m["style"]); err != nil {
		return out, fmt.Errorf("style: %w", err)
	}
	if out.Key, err = convert.String(m["key"]); err != nil {
		return out, fmt.Errorf("key: %w", err)
	}
	return out, nil
}

